<?php
require_once __DIR__.'/../includes/supervision-xlsx.php';
function layout_check(bool $ok,string $why):void {if(!$ok)throw new RuntimeException($why);}
$source=supervisor_write_xlsx([['EAN','COD','Producto','UXB'],['96385074','A','Primero',12],['4006381333931','B','Segundo',6]]);
$styled=supervisor_archive($source,function($zip){$path='xl/worksheets/sheet1.xml';$doc=supervisor_xml($zip[$path]->getContent());foreach($doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'row')as$row){$c=$doc->createElementNS(SUPERVISOR_XLSX_NS,'c');$c->setAttribute('r','E'.$row->getAttribute('r'));$row->appendChild($c);}$cols=$doc->createElementNS(SUPERVISOR_XLSX_NS,'cols');$col=$doc->createElementNS(SUPERVISOR_XLSX_NS,'col');foreach(['min'=>'1','max'=>'30','width'=>'10','customWidth'=>'1']as$key=>$value)$col->setAttribute($key,$value);$cols->appendChild($col);$doc->documentElement->insertBefore($cols,$doc->documentElement->firstChild);$zip[$path]=$doc->saveXML();return file_get_contents($zip->getPath());},true);
$out=supervisor_compare_xlsx($styled,'xl/worksheets/sheet1.xml',[3=>'4006381333931'],['96385074'=>25,'4006381333931'=>0],2,['stock'=>'Unidades','boxes'=>'Cajas'],['96385074'=>['stock'=>25,'boxes'=>'2 cajas × 12 + 1 unidad']],'A');
supervisor_archive($out,function($zip){[$doc,$rows]=supervisor_cells($zip,'xl/worksheets/sheet1.xml');layout_check(count($rows)===3,'Never inserts extra rows');layout_check($rows[1]['E']['value']==='Unidades'&&$rows[1]['F']['value']==='Cajas','Headers adjacent to last populated original column');layout_check($rows[2]['A']['value']==='96385074'&&$rows[2]['E']['value']==='25'&&$rows[2]['F']['value']==='2 cajas × 12 + 1 unidad','First product recovered with quantities on same row');layout_check($rows[3]['E']['value']==='0'&&$rows[3]['F']['value']==='0','Zero stock is numeric');$seen=[];foreach($doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'c')as$cell){$ref=$cell->getAttribute('r');layout_check(!isset($seen[$ref]),'No duplicate cell references');$seen[$ref]=true;}$last=0;foreach($doc->getElementsByTagNameNS(SUPERVISOR_XLSX_NS,'col')as$col){layout_check((int)$col->getAttribute('min')>$last,'Column ranges remain ordered and nonoverlapping');$last=(int)$col->getAttribute('max');}});
if(isset($argv[1]))file_put_contents($argv[1],$out);
echo "OK: styled blank cells, stale data-row header, no extra rows/columns, first product preserved, numeric zero, no duplicate cells or overlapping column ranges.\n";
